"""Independent regex-based reference implementation (different code path from gateway.py)."""
import re

ANON = "sip:anonymous@anonymous.invalid"
TOKEN = r"[A-Za-z0-9.!%*_+`'~\-]"
UC = r"[A-Za-z0-9\-_.!~*'()+]"
USER_RE = re.compile(r"(?:" + UC + r"|%(?:" + "|".join(
    [re.escape(c) for c in "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_.!~*'()+"]) + r")[0-9A-Fa-f]{2})*", re.I)
LABEL = r"[A-Za-z0-9](?:[A-Za-z0-9\-]{0,61}[A-Za-z0-9])?"
HOST_RE = re.compile(r"(?:" + LABEL + r"\.?)+")
SIP_RE = re.compile(r"(?i)^sip:(" + UC + r"(?:%[0-9A-Fa-f]{2}" + UC + r")*)@(" + LABEL + r"(?:\." + LABEL + r")*\.?)$")
TEL_RE = re.compile(r"(?i)^tel:\+([1-9][0-9]{0,14})$")
CALLID_RE = re.compile(r"^[A-Za-z0-9_.@+\-]{1,128}$")
CL_RE = re.compile(r"^[0-9]+$")
CSEQ_RE = re.compile(r"^([0-9]+)([ \t]+)(\S+)$")
HEXOK = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_.!~*'()+".lower()

def decode_user(u):
    out = []
    i = 0
    while i < len(u):
        if u[i] == "%":
            ch = chr(int(u[i+1:i+3], 16)); i += 3
        else:
            ch = u[i]; i += 1
        out.append(ch)
    return "".join(out)

def norm_uri(t):
    m = SIP_RE.match(t)
    if m:
        u, h = m.group(1), m.group(2)
        if len(h.rstrip(".")) > 253: return None
        return "sip:" + decode_user(u) + "@" + h.lower().rstrip(".")
    m = TEL_RE.match(t)
    if m:
        return "tel:+" + m.group(1)
    return None

def valid_uri(t):
    if norm_uri(t) is None: return False
    if t.startswith("<") or t.endswith(">"): return False
    # no whitespace, no illegal trailing
    return True

QS = r'"(?:[^"\\]|\\[ \t\x20-\x7e])*"'
ADDR_CORE = r"(?:(?:" + QS + r"|" + TOKEN + r"+(?:[ \t]+" + TOKEN + r"+)*)[ \t]*<|<)[ \t]*(?P<uri>sip:[^<>]*|tel:[^<>]*)[ \t]*>"
PARAM = r"[ \t]*;[ \t]*[Tt][Aa][Gg][ \t]*=[ \t]*" + TOKEN + r"{1,128}[ \t]*"
FULL = r"^(?:(?:(?:" + QS + r"|" + TOKEN + r"+(?:[ \t]+" + TOKEN + r"+)*)[ \t]*)?<" + r"[ \t]*" + r"(?P<uri>[^ \t<>]+)" + r"[ \t]*>" + PARAM + r"?|(?P<bare>[^ \t<>;]+)" + PARAM + r"?)[ \t]*$"
ADDR_RE = re.compile(FULL)

def parse_addr(v, params=True):
    if not params and (";" in v):
        pass
    m = ADDR_RE.match(v)
    if not m: return None
    uri = m.group("uri") or m.group("bare")
    if uri is None: return None
    if not params and m.group(0)[len(uri):].strip().startswith(";"):
        pass
    n = norm_uri(uri)
    if n is None: return None
    tail = m.group(0)
    tag = None
    if params:
        mt = re.search(r";[ \t]*[Tt][Aa][Gg][ \t]*=[ \t]*(" + TOKEN + r"{1,128})", tail[tail.index(uri) + len(uri):] if uri in tail else tail)
        if mt: tag = mt.group(1)
    else:
        after = tail[tail.index(uri) + len(uri):] if uri in tail else ""
        after = re.sub(r"^[ \t]*>", "", after)
        if after.strip(): return None
    return n, tag

def split_commas(v):
    parts = []
    cur = []
    depth = 0
    i = 0
    while i < len(v):
        c = v[i]
        if c == '"':
            m = re.match(QS, v[i:])
            if not m: return None
            cur.append(m.group(0)); i += len(m.group(0)); continue
        if c == "<": depth += 1
        if c == ">":
            depth -= 1
            if depth < 0: return None
        if c == "," and depth == 0:
            parts.append("".join(cur).strip(" \t")); cur = []; i += 1; continue
        cur.append(c); i += 1
    if depth != 0: return None
    parts.append("".join(cur).strip(" \t"))
    return parts

COMPACT = {"f":"from","t":"to","i":"call-id","l":"content-length","c":"content-type"}

def parse(text, ctx=None):
    if len(text) > 32768: return ("syntax", None)
    cut = text.find("\r\n\r\n")
    if cut < 0: return ("syntax", None)
    head = text[:cut]; body = text[cut+4:]
    for ch in body:
        if ch in "\t\r\n" or 32 <= ord(ch) <= 126: continue
        return ("syntax", None)
    lines = head.split("\r\n")
    for l in lines:
        for ch in l:
            if ch == "\t" or 32 <= ord(ch) <= 126: continue
            return ("syntax", None)
    rl = re.match(r"^(INVITE|MESSAGE) (SIP/[^ ]*|[^ ]+) SIP/2\.0$", lines[0])
    if not rl: return ("syntax", None)
    method = rl.group(1); ruri_raw = rl.group(2)
    if not ruri_raw.lower().startswith("sip:"): return ("syntax", None)
    ruri = norm_uri(ruri_raw)
    if ruri is None: return ("syntax", None)
    phys = lines[1:]
    if len(phys) > 512: return ("syntax", None)
    fields = []
    for l in phys:
        if l[:1] in (" ", "\t"):
            if not fields: return ("syntax", None)
            fields[-1] += " " + l.lstrip(" \t")
        else:
            fields.append(l)
    if len(fields) > 128: return ("syntax", None)
    got = {}
    order = []
    pai = []
    has_pai = False
    for f in fields:
        m = re.match("^(" + TOKEN + r"+)[ \t]*:", f)
        if not m: return ("syntax", None)
        name = m.group(1).lower()
        name = COMPACT.get(name, name)
        value = f[m.end():].strip(" \t")
        cnt = sum(1 for k in order if k == name)
        if name in ("from","to","call-id","cseq","content-length","p-preferred-identity",
                    "remote-party-id","privacy","content-type") and cnt:
            return ("syntax", None)
        order.append(name)
        if name == "from":
            r = parse_addr(value); 
            if not r: return ("syntax", None)
            got["from"] = r
        elif name == "to":
            r = parse_addr(value)
            if not r: return ("syntax", None)
            got["to"] = r
        elif name == "call-id":
            if not CALLID_RE.match(value): return ("syntax", None)
            got["call-id"] = value
        elif name == "cseq":
            m2 = CSEQ_RE.match(value)
            if not m2 or m2.group(3) != method: return ("syntax", None)
            num = int(m2.group(1))
            if not (1 <= num <= 2147483647): return ("syntax", None)
            got["cseq"] = num
        elif name == "content-length":
            if not CL_RE.match(value) or (value.lstrip("0") or "0") != str(len(body)): return ("syntax", None)
        elif name == "content-type":
            if not value: return ("syntax", None)
            got["content-type"] = value
        elif name == "privacy":
            if value.lower() == "id": got["privacy"] = "id"
            elif value.lower() == "none": got["privacy"] = "none"
            else: return ("syntax", None)
        elif name in ("p-preferred-identity","remote-party-id"):
            r = parse_addr(value, params=False)
            if not r or r[0] == ANON: return ("syntax", None)
            got[name] = r[0]
        elif name == "p-asserted-identity":
            has_pai = True
            members = split_commas(value)
            if members is None: return ("syntax", None)
            for mem in members:
                if not mem: return ("syntax", None)
                r = parse_addr(mem, params=False)
                if not r or r[0] == ANON: return ("syntax", None)
                pai.append(r[0])
        else:
            pass
    for nm in ("from","to","call-id","cseq","content-length"):
        if nm not in got and nm != "content-length": return ("syntax", None)
    if has_pai:
        if len(pai) > 2: return ("syntax", None)
        if len(pai) == 2 and (pai[0][:4].lower() == pai[1][:4].lower()): return ("syntax", None)
    return (None, {"method": method, "ruri": ruri, "from": got["from"], "to": got["to"],
                   "call-id": got["call-id"], "cseq": got["cseq"],
                   "content-type": got.get("content-type"), "privacy": got.get("privacy"),
                   "ppi": got.get("p-preferred-identity"), "rpid": got.get("remote-party-id"),
                   "pai": pai, "has_pai": has_pai, "body": body})

def domain_of(ident):
    return ident.split("@",1)[1] if ident.lower().startswith("sip:") and "@" in ident else None

def decide(job, index, results, ctx):
    if "raw" in job:
        text = job["raw"]
    else:
        src = job.get("source")
        if not isinstance(src,int) or src < 0 or src >= index or results[src]["status"] != "accept":
            return {"status":"reject","reason":"upstream"}
        text = results[src]["wire"]
    if not isinstance(text,str): return {"status":"reject","reason":"syntax"}
    err, r = parse(text)
    if err: return {"status":"reject","reason":err}
    gw = ctx["gateways"].get(job["gateway"], {})
    ing = job["ingress"]
    alias = ctx["alias"]
    fu = r["from"][0]
    private = (fu == ANON) or r["privacy"] == "id"
    to = job.get("trusted_out", False)
    if ing["kind"] == "untrusted":
        return {"status":"reject","reason":"unauthenticated"}
    if ing["kind"] == "local":
        acc = ctx["accounts"].get(ing["subject"])
        if acc is None: return {"status":"reject","reason":"unauthenticated"}
        pool = set([acc["primary"]] + list(acc.get("allow",[])))
        hosted = set(gw.get("local_domains",[]))
        sel = None
        if r["ppi"] is not None:
            ident = alias.get(r["ppi"])
            if ident is None or ident not in pool or domain_of(ident) not in hosted:
                return {"status":"reject","reason":"identity"}
            sel = ident
        if fu != ANON:
            ident = alias.get(fu)
            if ident is None or ident not in pool or domain_of(ident) not in hosted:
                return {"status":"reject","reason":"identity"}
            if sel is None: sel = ident
        if sel is None:
            ident = alias.get(acc["primary"])
            if ident is None or domain_of(ident) not in hosted:
                return {"status":"reject","reason":"identity"}
            sel = ident
        basis = "local"
    elif ing["kind"] == "peer":
        peers = gw.get("peers", {})
        if ing["name"] not in peers: return {"status":"reject","reason":"unauthenticated"}
        if not r["has_pai"]: return {"status":"reject","reason":"unauthenticated"}
        auth = set(peers[ing["name"]])
        idents = [alias.get(c) for c in r["pai"]]
        if any(i is None for i in idents) or len(set(idents)) != 1:
            return {"status":"reject","reason":"identity"}
        sel = idents[0]
        if domain_of(sel) not in auth: return {"status":"reject","reason":"identity"}
        for c in [fu] + ([r["ppi"]] if r["ppi"] else []) + ([r["rpid"]] if r["rpid"] else []):
            if c == ANON: continue
            if alias.get(c) != sel: return {"status":"reject","reason":"identity"}
        basis = "peer"
    else:
        return {"status":"reject","reason":"unauthenticated"}
    hdr = [r["method"] + " " + r["ruri"] + " SIP/2.0"]
    fu_out = ANON if private else sel
    line = "From: <" + fu_out + ">"
    if r["from"][1]: line += ";tag=" + r["from"][1]
    hdr.append(line)
    line = "To: <" + r["to"][0] + ">"
    if r["to"][1]: line += ";tag=" + r["to"][1]
    hdr.append(line)
    hdr.append("Call-ID: " + r["call-id"])
    hdr.append("CSeq: %d %s" % (r["cseq"], r["method"]))
    hdr.append("Privacy: " + ("id" if private else "none"))
    if (not private) or to: hdr.append("P-Asserted-Identity: <" + sel + ">")
    if r["content-type"] is not None: hdr.append("Content-Type: " + r["content-type"])
    hdr.append("Content-Length: " + str(len(r["body"])))
    wire = "\r\n".join(hdr) + "\r\n\r\n" + r["body"]
    return {"status":"accept","identity":sel,"basis":basis,"private":bool(private),"wire":wire}

def process(batch):
    alias = {}
    for canon, als in batch.get("directory", {}).items():
        alias[canon] = canon
        for a in als or []: alias[a] = canon
    ctx = {"alias": alias, "accounts": batch.get("accounts", {}), "gateways": batch.get("gateways", {})}
    out = []
    for i, job in enumerate(batch.get("jobs", [])):
        out.append(decide(job, i, out, ctx))
    return {"results": out}
